import cv2
import pickle
import numpy as np
import imageio.v3 as iio
from pathlib import Path
from matplotlib import cm

#path to the paired data from pipe_compare.py
#replace with the actual folder name generated by the pipe
data_path = "point_track/saved_videos/compare_v_BodyWeightSquats_g21_c04_vs_v_BodyWeightSquats_g22_c03/paired_trajectories.pkl"

with open(data_path, "rb") as f:
    data = pickle.load(f)

#extract info for both subjects
coach = data["coach"]
student = data["student"]

#load the specific frames used for the initial semantic anchor
img_c = iio.imread(coach["video_path"], plugin="FFMPEG")[coach["query_frame"]]
img_s = iio.imread(student["video_path"], plugin="FFMPEG")[student["query_frame"]]

#get original dimensions for scaling math
hc, wc = img_c.shape[:2]
hs, ws = img_s.shape[:2]

#resize to match height for a clean side-by-side view
target_h = max(hc, hs)
img_c_res = cv2.resize(img_c, (int(wc * (target_h / hc)), target_h))
img_s_res = cv2.resize(img_s, (int(ws * (target_h / hs)), target_h))

#create the horizontal canvas
canvas = np.hstack([img_c_res, img_s_res])
offset_x = img_c_res.shape[1]

#setup the colors - index-based colors ensure the "same" point has the same color
num_points = coach["tracks"].shape[2]
colors = (cm.rainbow(np.linspace(0, 1, num_points))[:, :3] * 255).astype(np.uint8)

#loop through all points - no mapping dict needed now!
for i in range(num_points):
    #grab raw (x, y) coordinates for the query frame
    pc = coach["tracks"][0, coach["query_frame"], i]
    ps = student["tracks"][0, student["query_frame"], i]
    
    #scale coordinates to match the resized canvas dimensions
    cc = (int(pc[0] * (img_c_res.shape[1] / wc)), int(pc[1] * (target_h / hc)))
    cs = (int(ps[0] * (img_s_res.shape[1] / ws)) + offset_x, int(ps[1] * (target_h / hs)))
    
    color = tuple(map(int, colors[i]))
    
    #draw the anchor points
    cv2.circle(canvas, cc, 4, color, -1)
    cv2.circle(canvas, cs, 4, color, -1)
    
    #draw the correspondence line
    #if these lines are horizontal and don't cross, the dino projection worked perfectly
    cv2.line(canvas, cc, cs, color, 1, cv2.LINE_AA)

#save the verification image back into the same directory
out_dir = Path(data_path).parent
out_path = out_dir / "paired_semantic_verification.png"
cv2.imwrite(str(out_path), cv2.cvtColor(canvas, cv2.COLOR_RGB2BGR))

print(f"saved paired visualization to {out_path}")